"""Build Kubiak 2009 rows from parsed Appendix 1 (kub_rows.json)."""
import json, re, sys
sys.path.insert(0, ".")
from h import append, remove, log
R = json.load(open("kub_rows.json"))
stem = "Kubiak_Cunn_2009"

def yrs(x):  # weeks -> years, 3 decimals, no trailing zeros
    v = round(float(x) / 52, 3)
    return ("%.3f" % v).rstrip("0").rstrip(".")

def parse_time(cell):
    """Return (value, unit, flags) for the first time in a cell, or None for text."""
    s = re.sub(r"</?u>", "", cell).strip()
    m = re.fullmatch(r"At least (\d+) years", s)
    if m: return (">" + m.group(1), "y", {"text"})
    m = re.fullmatch(r"Less than (\d+) years?", s)
    if m: return ("<" + m.group(1), "y", {"text"})
    pieces = [p for p in re.split(r",|\*\*| & ", s) if p.strip()]
    first = pieces[0].strip()
    flags = set()
    if s.startswith("**"): flags.add("bold")
    m = re.match(r"^(c\.\s?)?(\?)?(\d+(?:\.\d+)?)(?:–(\d+(?:\.\d+)?))?(\+)?\s?([wy])?", first)
    if not m or not m.group(3): return None
    if m.group(1): flags.add("c")
    if m.group(2) or "?" in first: flags.add("?")
    unit = m.group(6)
    if not unit:
        mu = re.search(r"\d\s?\+?([wy])", s); unit = mu.group(1) if mu else None
    if not unit: return None
    lo, hi = m.group(3), m.group(4)
    if m.group(5): val = ">" + lo; flags.add("+")
    else: val = lo + ("-" + hi if hi else "")
    if len(pieces) > 1 or not re.fullmatch(r"\d+(\.\d+)?[wy]", s): flags.add("extra")
    return (val, unit, flags)

def to_years(val, unit):
    if unit == "y": return val
    pre = val[0] if val[0] in "<>" else ""
    parts = val.lstrip("<>").split("-")
    return pre + "-".join(yrs(p) for p in parts)

