        rt="; ".join(dict.fromkeys(orgs))
    n.append(f"regeneration strategy printed '{reg}' ({r['sec'].lower()})")
    repr3=repr3a=""
    m=re.fullmatch(r"F([123])(\(\?\)|\?)?",fl)
    if m:
        v=m.group(1)
        if m.group(2): n.append(f"first flowering printed '{fl}' (uncertain)")
    elif fl=="F1 or F2": v="1-2"; n.append("first flowering printed 'f1 or f2'")
    elif fl=="F3?": v="3"
