    if fl=="F3?": n.append("first flowering printed 'f3?' (uncertain)")
    if fl=="?" and g!="Amyema": n.append("first flowering printed '?'")
    base_nm=" ".join(parts[:2])
    if not v and base_nm in NOT3_OSR and r["sec"]=="OSR":
        v=">3"; n.append("not flowering at year 3; 'all 12 species flowered by 10 years post-fire' (p. 31)")
    elif not v and base_nm in NOT3_ALL:
        n.append("not flowering at year 3; flowered by 10 years post-fire (p. 31)")
    if r["sec"]=="OSR": repr3=v
    elif r["sec"]=="ORR": repr3a=v
