    if "rare" in reg: n.append("'rare' = seedling regeneration rare")
    if g in ("Cladia","Asterella","Anthoceros","Cephaloziella","Lethocolea","Lophocolea","Marchantia","Symphogyna","Barbula","Bryum","Breutelia","Campylopus","Ceratodon","Funaria","Polytrichum","Wijkia"):
        n.append("non-vascular plant: flowering = spore or fruiting body production")
    if g=="Marchantia": n.append("species printed 'marchantia polymorpha'; methods state this species was in fact marchantia berteroana (p. 10)")
    if "f2" in subs: n.append("subsite f2 also burnt by the peat fire")
    loc="; ".join(subs)
    out.append(dict(genus=g,species=sp,subsp=sub,native_status="introduced" if (r["intro"] or info["intro"]) else "",family=info["fam"] or "",
        fire_response_categorical_surv1=fr,resprouter_type=rt,age_at_first_flower_production_from_seed_repr3=repr3,time_to_first_flower_production_resprout_repr3a=repr3a,
        location_name=loc,rainfall_mm="657",fire_type="wildfire",fire_season_categorical="summer",fire_severity_categorical="high",
        data_location=f"table 5, p. {r['page']}; site: table 3, pp"[:0]+f"table 5, p. {r['page']}"+("; fire response: text, p. 31" if g=="Amyema" else ""),
        notes="; ".join(n+[pw]),source=src,file_name=stem))
print(remove(stem)); print(append(out))
print(log(stem,"done",started,"removed 0 leftover rows; Tables 3 and 5 parsed with one-off code (random rows checked); Table 5 values pooled across subsites, so each row is placed on the subsite(s) where Table 3 records the species in years 1-3; FRR first flowering kept in notes (seed vs regrowth unclear); Hymenophyllum cupressiforme no row (codes '?')"))
